import * as THREE from 'three/webgpu';
import { texture, uv, vec2 } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();
  group.name = 'hub-features-card-2-label';
  group.position.set(3.2, 1, 0.06);
  group.rotation.set(0, 0, 0);
  group.scale.set(1, 1, 1);

  const atlasRect = { x: 0, y: 0, w: 512, h: 320, atlasSize: 512 };
  const aspect = atlasRect.w / atlasRect.h;
  const planeHeight = 0.34;
  const planeWidth = planeHeight * aspect;

  const geometry = new THREE.PlaneGeometry(planeWidth, planeHeight);

  const map = ctx.textureLoader.load('/prism-assets/chrome/ceramic-grain.map.png');
  map.colorSpace = THREE.SRGBColorSpace;
  map.wrapS = THREE.ClampToEdgeWrapping;
  map.wrapT = THREE.ClampToEdgeWrapping;

  const uOffset = atlasRect.x / atlasRect.atlasSize;
  const vOffset = 1.0 - (atlasRect.y + atlasRect.h) / atlasRect.atlasSize;
  const uScale = atlasRect.w / atlasRect.atlasSize;
  const vScale = atlasRect.h / atlasRect.atlasSize;

  const atlasUV = uv().mul(vec2(uScale, vScale)).add(vec2(uOffset, vOffset));

  const material = new THREE.MeshBasicNodeMaterial();
  material.map = map;
  material.colorNode = texture(map, atlasUV);
  material.transparent = true;
  material.depthWrite = false;

  const plane = new THREE.Mesh(geometry, material);
  plane.name = 'label-plane';
  group.add(plane);

  const textMesh = ctx.fontAtlas.createText({
    text: 'Features 3',
    font: 'Lora',
    weight: 400,
    size: 39 / 512,
    color: config?.colors?.paper || '#e8ecf2',
    anchor: 'center',
  });
  textMesh.position.set(0, 0, 0.001);
  group.add(textMesh);

  group.userData.handlers = {};

  group.onBeforeRender = (renderer, scene, camera) => {
    group.quaternion.copy(camera.quaternion);
  };

  group.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    if (map && map.dispose) map.dispose();
    if (textMesh) {
      if (textMesh.geometry) textMesh.geometry.dispose();
      if (textMesh.material) textMesh.material.dispose();
    }
    group.onBeforeRender = null;
  };

  return group;
}
